	"dataSources": {
		"ds_1098GVGh": {
			"name": "SUMMARY - Single Value - Total Service Category",
			"options": {
				"extend": "ds_BASEwithFILTER",
				"query": "| stats dc(ServiceCategory)"
			},
			"type": "ds.chain"
		},
		"ds_1WRzJnmj": {
			"name": "ANALYZE - SingleValue - Resource with no tags",
			"options": {
				"extend": "ds_BASEwithFILTER",
				"query": "`focus_tag`\n`focus_tag_timetable` \n| stats latest(no_tag) as no_tag by _time\n| where no_tag like(\"%\")"
			},
			"type": "ds.chain"
		},
		"ds_24yEwVJS": {
			"name": "SUMMARY - SingleValue - Total Services",
			"options": {
				"extend": "ds_BASEwithFILTER",
				"query": "| stats dc(ServiceName)"
			},
			"type": "ds.chain"
		},
		"ds_3jGSlQgw": {
			"name": "ANALYZE - SingelValue Trellis - Tag Coverage over Group by",
			"options": {
				"extend": "ds_BASEwithFILTER",
				"query": "`focus_tag`\n| stats max(with_tag) as with_tag  min(no_tag) as no_tag dc(ResourceId) as total by ResourceId $GroupBy$ \n| stats sum(with_tag) as with_tag sum(no_tag) as no_tag sum(total) as total by $GroupBy$\n| eval with_perc = if(isnull(round(100*with_tag/total,2)), 0, round(100*with_tag/total,2))\n| fields $GroupBy$ with_perc"
			},
			"type": "ds.chain"
		},
		"ds_4wtvH8LP": {
			"name": "SUMMARY - SingleValue - Total Provider",
			"options": {
				"extend": "ds_BASEwithFILTER",
				"query": "| stats dc(ProviderName)"
			},
			"type": "ds.chain"
		},
		"ds_6AhezFiK": {
			"name": "FILTER - Dropdown - Charge Category",
			"options": {
				"extend": "ds_BASEwithFILTER",
				"query": "| dedup ChargeCategory\n| table ChargeCategory"
			},
			"type": "ds.chain"
		},
		"ds_6w4QpChN": {
			"name": "ANALYZE - Bar - Tagged by ServiceCategory",
			"options": {
				"extend": "ds_BASEwithFILTER",
				"query": "`focus_tag`\n| stats max(with_tag) as with_tag  min(no_tag) as no_tag dc(ResourceId) as total by ResourceId $GroupBy$ \n| stats sum(with_tag) as with_tag sum(no_tag) as no_tag sum(total) as total by $GroupBy$\n| eval with_perc = if(isnull(round(100*with_tag/total,2)), 0, round(100*with_tag/total,2))\n| fields $GroupBy$ with_perc"
			},
			"type": "ds.chain"
		},
		"ds_79PyipUi": {
			"name": "SUMMARY - Table - Effective Cost by Service Category",
			"options": {
				"extend": "ds_BASEwithFILTER",
				"query": "| timechart eval(round(sum(sumEffectiveCost),2)) as EffectiveCost BY ServiceCategory \n| addtotals label=Total"
			},
			"type": "ds.chain"
		},
		"ds_9cwzwFjs": {
			"name": "TREND - fixed Period - Table - Percent Change by Group",
			"options": {
				"query": "| `focus_base_search`\n| bin _time span=1mon \n| stats sum(eval(round(sumEffectiveCost,2))) as EffectiveCost by _time $GroupBy$ BillingCurrency \n    ```missing month with fill with 0 ```\n| eval SvcCur = $GroupBy$.\"|\".BillingCurrency \n| timechart span=1mon sum(EffectiveCost) as EffectiveCost by SvcCur limit=0 \n| fillnull value=0 \n| untable _time SvcCur EffectiveCost \n| rex field=SvcCur \"(?<$GroupBy$>.*)\\|(?<BillingCurrency>.*)\"\n    ```MoM calculation```\n| sort $GroupBy$ _time \n| streamstats current=f last(EffectiveCost) as prevCost by $GroupBy$ BillingCurrency \n| eval prevCost = if(isnull(prevCost), 0, prevCost) \n| eval mom_abs = if(isnull(prevCost), 0, round(EffectiveCost - prevCost,2)) \n| eval mom_pct = case(\n    prevCost=0 AND EffectiveCost>0, 100.00,\n    prevCost=0 AND EffectiveCost=0, null(),\n    true(), round((EffectiveCost - prevCost)/prevCost*100,2)\n)\n\n```set timeframe -1month to avoid values from the actual month```\n| eventstats latest(_time) as t0 \n| eval t0_prev = relative_time(t0,\"@mon\") \n| eval t2 = relative_time(t0_prev,\"-12mon@mon\") \n| where _time>=t2 AND _time<=t0_prev\n    ```define table values and xyseries```\n| eval col = strftime(_time,\"%b\") \n| fields $GroupBy$ col mom_pct \n| xyseries $GroupBy$ col mom_pct \n    ```transpose to sort columns over month```\n| transpose 0 \n| eval sortorder = case(column=\"$GroupBy$\", 0, column=\"Jan\",1, column=\"Feb\",2, column=\"Mar\",3, column=\"Apr\",4,\n    column=\"May\",5, column=\"Jun\",6, column=\"Jul\",7, column=\"Aug\",8,\n    column=\"Sep\",9, column=\"Oct\", 10, column=\"Nov\", 11, column=\"Dec\", 12, 1==1, 99) \n| sort + sortorder \n| fields - sortorder\n    ```transpose back to table```\n| transpose 0 header_field=column \n| fields - column\n\n```format month output values```\n| foreach Jan, Feb, Mar, Apr, May, Jun, Jul, Aug, Sep, Oct, Nov, Dec [\n    eval <<FIELD>> = case(\n    <<FIELD>> = 0, \"⦿ \".tostring(abs('<<FIELD>>'),\"commas\").\" %\",\n    <<FIELD>> < 0, \"▼ \".tostring(abs('<<FIELD>>'),\"commas\").\" %\",\n    <<FIELD>> > 0, \"▲ \".tostring(abs('<<FIELD>>'),\"commas\").\" %\", 1==1, null())\n    ]",
				"queryParameters": {
					"earliest": "-12mon@mon",
					"latest": "@mon"
				}
			},
			"type": "ds.search"
		},
		"ds_BASEwithFILTER": {
			"name": "BASE Search with Filter",
			"options": {
				"query": "| `focus_search`\nAND cost.ProviderName IN ($ProviderName|s$) \nAND cost.BillingAccountName IN ($BillingAccountName|s$) \nAND cost.ChargeCategory IN ($ChargeCategory|s$) \nAND cost.SubAccountName IN ($SubAccountName|s$) \nAND cost.ServiceCategory IN ($ServiceCategory|s$)\nAND cost.ServiceName IN ($ServiceName|s$) \nAND cost.ResourceId IN ($ResourceId|s$) \nAND cost.RunTags IN ($TagKey|s$) \nAND cost.RunTags IN ($TagValue|s$)\n`focus_tstats_by`",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_Dropdown_ServiceName": {
			"name": "FILTER - Dropdown - Service Name",
			"options": {
				"extend": "ds_BASEwithFILTER",
				"query": "| dedup ServiceName \n| table ServiceName"
			},
			"type": "ds.chain"
		},
		"ds_FdPke2q4": {
			"name": "ANALYZE - SingleValue - Resource with tags",
			"options": {
				"extend": "ds_BASEwithFILTER",
