		"ds_L24Vo6rM": {
			"name": "TREND - fixed Period - Line - MoM Effective Cost Change by Group",
			"options": {
				"query": "| `focus_base_search`\n| timechart span=1mon sum(eval(round(sumEffectiveCost,2))) as EffectiveCost by $GroupBy$",
				"queryParameters": {
					"earliest": "-12mon@mon",
					"latest": "@mon"
				}
			},
			"type": "ds.search"
		},
		"ds_MS2qT1QY": {
			"name": "TREND - fixed Period - Table - Effective Cost per Top 10 Resource",
			"options": {
				"query": "| `focus_base_search` \n| stats sum(eval(round(sumConsumedQuantity,4))) as ConsumedQuantity sum(eval(round(sumEffectiveCost,2))) as EffectiveCost by ConsumedUnit ResourceId ProviderName BillingAccountId SubAccountName ServiceCategory BillingCurrency \n| addtotals row=true EffectiveCost \n| stats values(ProviderName) as \"Provider Name\" values(BillingAccountId) as \"Billing Account\" values(SubAccountName) as \"Sub Account\" values(ServiceCategory) as \"Service Category\" values(BillingCurrency) as BillingCurrency values(ConsumedUnit) as \"Consumed Units\" values(ConsumedQuantity) as \"Consumed Quantity\" values(EffectiveCost) as \"Effective Cost\" sum(eval(round(Total,2))) as Total by ResourceId \n| rename ResourceId as \"Resource Id\" \n| sort 0 -Total \n| head 10 \n| eval Total = tostring(Total,\"commas\").\" \".BillingCurrency\n| table \"Resource Id\", \"Service Category\", \"Consumed Units\", \"Consumed Quantity\", \"Effective Cost\", Total",
				"queryParameters": {
					"earliest": "-30d@d",
					"latest": "@d"
				}
			},
			"type": "ds.search"
		},
		"ds_OI4bXS1d": {
			"name": "SUMMARY - Table - Effective Cost by Service Name",
			"options": {
				"extend": "ds_BASEwithFILTER",
				"query": "| timechart eval(round(sum(sumEffectiveCost),2)) as EffectiveCost by ServiceName \n| addtotals label=Total"
			},
			"type": "ds.chain"
		},
