			"name": "TREND - fixed Period- Column - Effective Cost Top 10 Resource",
			"options": {
				"query": "| `focus_base_search` \n| timechart sum(eval(round(sumEffectiveCost,2))) as EffectiveCost span=1d by ResourceId \n| addtotals fieldname=Total ",
				"queryParameters": {
					"earliest": "-30d@d",
