		},
		"ds_pciCswG4": {
			"name": "SUMMARY - Donat - Regions by Name",
			"options": {
				"extend": "ds_BASEwithFILTER",
				"query": "| stats sum(sumEffectiveCost) as EffectiveCost by RegionId RegionName ProviderName\n| table RegionName EffectiveCost\n| sort - EffectiveCost"
			},
			"type": "ds.chain"
		},
		"ds_qOKt7EqQ": {
			"name": "FORCAST - fixed Period - Column - Prediction over month",
			"options": {
				"query": "| `focus_base_search` \n| timechart span=1mon sum(eval(round(sumEffectiveCost,2))) as EffectiveCost\n| predict EffectiveCost algorithm=LLT holdback=1",
				"queryParameters": {
					"earliest": "-4mon@mon",
					"latest": "now"
				}
			},
			"type": "ds.search"
		},
		"ds_sN98RtRb": {
			"name": "SUMMARY - Map - Effective Cost by RegionId",
			"options": {
				"extend": "ds_BASEwithFILTER",
				"query": "| stats sum(sumEffectiveCost) as EffectiveCost by RegionId RegionName ProviderName\n| lookup cloudregions region_id AS RegionId provider AS ProviderName OUTPUT city country lat lon provider\n| geostats latfield=lat longfield=lon sum(EffectiveCost) by RegionName"
			},
			"type": "ds.chain"
		},
		"ds_tauTbTvN": {
			"name": "ANALYZE - Table - ResourceId Tag",
			"options": {
				"extend": "ds_BASEwithFILTER",
				"query": "| rex field=Tags max_match=0 \"(?:(?:\\\"{1,2}|')(?<tag_keys>[^\\\"':]+)(?:\\\"{1,2}|')\\s*:\\s*(?:\\\"{1,2}|')(?<tag_values>[^\\\"']*)(?:\\\"{1,2}|'))\" \n| eval has_tag = if(RunTags==\"n/a\", 0, 1) \n| eval tag_keys = if(isnull(tag_keys), \"n/a\", tag_keys) \n| eval tag_values = if(isnull(tag_values), \"n/a\", tag_values) \n| stats sum(eval(round(sumConsumedQuantity,4))) as ConsumedQuantity sum(eval(round(sumEffectiveCost,2))) as EffectiveCost values(has_tag) as has_tag values(tag_keys) as tag_keys values(tag_values) as tag_values values(_time) as _time by ConsumedUnit ResourceId ProviderName BillingAccountId SubAccountName ServiceCategory ServiceName BillingCurrency \n| addtotals row=true EffectiveCost \n| stats values(ProviderName) as \"Provider Name\" values(BillingAccountId) as \"Billing Account\" values(SubAccountName) as \"Sub Account\" values(ServiceCategory) as \"Service Category\" values(ServiceName) as \"Service\" values(has_tag) as has_tag values(tag_keys) as tag_keys values(tag_values) as tag_values values(BillingCurrency) as BillingCurrency values(ConsumedUnit) as \"Consumed Units\" values(ConsumedQuantity) as \"Consumed Quantity\" values(EffectiveCost) as \"Effective Cost\" sum(eval(round(Total,2))) as Total latest(_time) as _time by ResourceId \n| eval Total = tostring(Total,\"commas\").\" \".BillingCurrency \n| eval _tok = case(\"$tok_tag_filter$\"=\"*\", \"*\",\n    \"$tok_tag_filter$\"=\"1\", \"1\",\n    \"$tok_tag_filter$\"=\"0\", \"0\",\n    true(), \"*\") \n| where (_tok=\"*\" OR has_tag=_tok) \n| fields - has_tag _tok \n| rename ResourceId as \"Resource Id\" tag_keys as Tag tag_values as Values\n| eval \"Last Seen\" = strftime(_time, \"%Y-%m-%d\")\n| table \"Last Seen\" \"Resource Id\", \"Service Category\", \"Service\", Tag, Values, \"Consumed Units\", \"Consumed Quantity\", \"Effective Cost\", Total\n| sort - \"Last Seen\""
			},
			"type": "ds.chain"
		},
		"ds_tgeJ5HIg": {
			"name": "ANALYZE - SingleValue - EffectiveCost with tags",
			"options": {
				"extend": "ds_BASEwithFILTER",
				"query": "`focus_tag`\n| stats sum(eval(round(sumEffectiveCost,2))) as Total by with_tag\n| fields Total"
			},
